module multi_16bit(
    input clk, input rst_n, input start, input [15:0] ain, input [15:0] bin, output [31:0] yout, output done
);
    // TODO: implement your unsigned 16-bit multiplier with shift and accumulate operations here.
    // You may declare your own wires and registers, but do not modify the existing ports.
    // Note: You may NOT use any arithmetic operators (e.g., +, *, etc.) and the shift operations must be done with concatenation operators (e.g., {a,b}).
    // You may also use the operator shorthand (e.g., +=, *=, etc.) in your combinational logic.
    // Your code starts here
    reg [4:0] i;
    reg done_r;
    reg [15:0] areg;
    reg [15:0] breg;
    reg [31:0] yout_r;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'd0;
        end else begin
            if (start && i < 17) begin
                i <= i + 1;
            end else begin
                i <= 5'd0;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done_r <= 1'b0;
        end else begin
            if (i == 16) begin
                done_r <= 1'b1;
            end else if (i == 17) begin
                done_r <= 1'b0;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            areg <= 16'd0;
            breg <= 16'd0;
            yout_r <= 32'd0;
        end else if (start) begin
            if (i == 0) begin
                areg <= ain;
                breg <= bin;
            end else if (i < 17 && areg[i-1]) begin
                yout_r <= yout_r + (breg << (i-1));
            end
        end
    end
    // Your code ends here
    assign yout = yout_r;
    assign done = done_r;
endmodule
